import pytest

from account_enum_guard import validate

BAD_VALUES = [
  "user not found",
  "wrong password",
  "account locked",
  "账号不存在",
  "密码错误",
  "用户已锁定",
  "no such user: alice",
  "invalid password for uid=1001",
  "user_id 42 not found",
  "email does not exist",
  "too many failures, locked",
  "",
  "",
  "internal error: no row for alice",
  "unknown account: admin"
]


@pytest.mark.parametrize("value", BAD_VALUES)
def test_bad_value_is_rejected(value):
    with pytest.raises((ValueError, TypeError)):
        validate(value)
